function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(69501);
var T0=Date.now();/*Signature edition*/
var T=100,N=4;
var cap=[];for(var i=0;i<N;i++)cap.push(Math.ceil(T/N)+2);
var moved=0,movedRand=0;
for(var i=0;i<T;i++){var home=Math.floor(R()*N);
  if(cap[home]>0){cap[home]--;}
  else{var alt=0,best=1e9;for(var n=0;n<N;n++)if(cap[n]>0){var d=Math.abs(n-home);if(d<best){best=d;alt=n;}}cap[alt]--;moved+=best*10;}
  var rh=Math.floor(R()*N);if(rh!==home)movedRand+=Math.abs(rh-home)*10;}
console.log(JSON.stringify({id:"JAH-APX69S-000001",ok:true,metrics:{tasks:T,nodes:N,bytes_moved_local:Math.round(moved),bytes_moved_random:Math.round(movedRand),reduction_pct:+((1-moved/Math.max(movedRand,1))*100).toFixed(1)},ms:Date.now()-T0}));

